public async Task HandleAsync(IEvent @event, CancellationToken ct)
{
    switch (@event)
    {
        case OrderShipped e:
            await UpdateOrderAsync(e.OrderId, e.TrackingNumber, ct);
            break;
        case OrderShippedV2 e:
            await UpdateOrderAsync(
                e.OrderId,
                e.TrackingNumber,
                e.Carrier,
                ct);
            break;
    }
}
